/* cppi::00bbbbb7a3093e0aea4afcbe870698217f59b87f4a050b21c46aa35a25d80018 */
SELECT finance_accounting.scd_finance_transactions_entity.*, trades_deals.scd_transactions_entity.abor_security_id, trades_deals.scd_transactions_entity.abor_security_name 
FROM finance_accounting.scd_finance_transactions_entity
JOIN trades_deals.scd_transactions_entity
ON finance_accounting.scd_finance_transactions_entity.transaction_number = trades_deals.scd_transactions_entity.abor_transaction_number
WHERE finance_accounting.scd_finance_transactions_entity.business_date = '2025-02-06' limit 500 -- {"user": "ltian@cppib.com", "source": "pyxll"}

